<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/** Immutable audit row (§4.5). UPDATE/DELETE are rejected by a database trigger. */
/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string|null $actor_id
 * @property string|null $actor_name
 * @property bool $actor_is_system
 * @property string $action
 * @property string $severity
 * @property string|null $target_type
 * @property string|null $target_id
 * @property string|null $target_label
 * @property string|null $detail
 * @property array|null $before
 * @property array|null $after
 * @property array|null $metadata
 * @property string|null $ip_address
 * @property string|null $user_agent
 * @property string|null $request_id
 * @property Carbon $created_at
 */
/* @properties-end */
class AuditLog extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'au';

    public $timestamps = false;

    protected $fillable = [
        'actor_id', 'actor_name', 'actor_is_system', 'action', 'severity', 'target_type', 'target_id', 'target_label',
        'detail', 'before', 'after', 'metadata', 'ip_address', 'user_agent', 'request_id', 'created_at',
    ];

    protected function casts(): array
    {
        return [
            'before' => 'array',
            'after' => 'array',
            'metadata' => 'array',
            'actor_is_system' => 'boolean',
            'created_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function actor(): BelongsTo
    {
        return $this->belongsTo(User::class, 'actor_id');
    }
}
